(()=>{var l=document.getElementById("loginForm");l.addEventListener("submit",t=>{t.preventDefault();let o=l.querySelectorAll("#loginForm input"),e={};o.forEach(n=>{let i=n.getAttribute("name"),c=n.value;e[i]=c}),r(e)});function r(t){let o=JSON.stringify(t);fetch("/login",{body:o,method:"POST",headers:{"Content-Type":"application/json"}}).then(e=>{e.ok?location.reload():console.error(e)})}})();
